<?php
require_once __DIR__.'/config/config.php';require_login();$uid=(int)$_SESSION['user_id'];$errors=[];$stmt=$conn->prepare('SELECT id,animal_code,name FROM animals WHERE owner_id=? AND status="Active" ORDER BY animal_code');$stmt->bind_param('i',$uid);$stmt->execute();$animals=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$animal_id=(int)($_POST['animal_id']??0);$date=$_POST['record_date']??'';$type=trim($_POST['service_type']??'');$details=trim($_POST['details']??'');$provider=trim($_POST['provider_name']??'');$due=$_POST['next_due_date']?:null;if(!$animal_id||$type===''||$date==='')$errors[]='Choose an animal, date and service type.';$check=$conn->prepare('SELECT id FROM animals WHERE id=? AND owner_id=?');$check->bind_param('ii',$animal_id,$uid);$check->execute();if(!$check->get_result()->num_rows)$errors[]='Choose an animal from your own records.';if(!$errors){$stmt=$conn->prepare('INSERT INTO health_records(animal_id,record_date,service_type,details,provider_name,next_due_date,entered_by) VALUES(?,?,?,?,?,?,?)');$stmt->bind_param('isssssi',$animal_id,$date,$type,$details,$provider,$due,$uid);$stmt->execute();if($due){$animalstmt=$conn->prepare('SELECT animal_code FROM animals WHERE id=?');$animalstmt->bind_param('i',$animal_id);$animalstmt->execute();$ac=$animalstmt->get_result()->fetch_assoc()['animal_code'];$title=$type.' follow-up — '.$ac;$rm=$conn->prepare("INSERT INTO reminders(owner_id,animal_id,title,due_date,notes) VALUES(?,?,?,?,?)");$rm->bind_param('iisss',$uid,$animal_id,$title,$due,$details);$rm->execute();}flash('Health record saved.');header('Location: health.php');exit;}}
$page_title='Add health record';require __DIR__.'/includes/header.php';
?>
<?php foreach($errors as $err):?><div class="alert error"><?=e($err)?></div><?php endforeach;?><?php if(!$animals):?><div class="alert info">Register an active animal before adding a health record. <a class="link" href="animal_add.php">Register livestock →</a></div><?php else:?><div class="form-card"><div class="panel-heading"><div><h3>Record a service or visit</h3><p>Enter information from your records or service provider.</p></div></div><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="form-grid"><div class="field full"><label>Livestock *</label><select name="animal_id" required><option value="">Choose livestock</option><?php foreach($animals as $a):?><option value="<?=$a['id']?>"><?=e($a['animal_code'].' '.($a['name']?:''))?></option><?php endforeach;?></select></div><div class="field"><label>Record date *</label><input type="date" name="record_date" required max="<?=date('Y-m-d')?>" value="<?=date('Y-m-d')?>"></div><div class="field"><label>Service type *</label><select name="service_type" required><option value="">Choose service</option><option>Vaccination</option><option>Veterinary visit</option><option>Treatment recorded</option><option>Dipping / parasite control</option><option>Routine inspection</option><option>Other</option></select></div><div class="field"><label>Provider name</label><input name="provider_name" maxlength="120" placeholder="Vet / service provider"></div><div class="field"><label>Next due date (optional)</label><input type="date" name="next_due_date" min="<?=date('Y-m-d')?>"></div><div class="field full"><label>Details</label><textarea name="details" placeholder="Record relevant information provided by the service provider"></textarea></div></div><div class="form-actions"><button class="btn btn-primary">Save record</button><a class="btn btn-light" href="health.php">Cancel</a></div></form></div><?php endif;?>
